function parseJsonSafe(value, fallback) {
  if (!value) return fallback;
  if (Array.isArray(value) || typeof value === 'object') return value;

  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

const rawResponse = $input.first()?.json?.data ?? $input.first()?.json ?? [];
const chunks = parseJsonSafe(rawResponse, []);

const contextoIa = $('Obter contexto IA').first().json || {};
const resolucaoBusca = $('Normalizar resolucao de busca').first().json || {};
const sessaoToken = $('Iniciar sessao').first().json.data || null;

const total_tokens_contextoIA = Number(resolucaoBusca.total_tokens_resolucao_busca || 0);
let total_tokens_embeddings = 0;
try {
  total_tokens_embeddings = Number($('Gerar embedding OpenRouter do chunk').first().json.usage?.total_tokens || 0);
} catch {}
const total_tokens = total_tokens_contextoIA + total_tokens_embeddings;

const metadata = {
  _rag_contextual: true,
  sessao_token: sessaoToken,
  contexto_ia: contextoIa,
  resolucao_busca: resolucaoBusca,
  pergunta_busca: resolucaoBusca.pergunta_busca || $('When Executed by Another Workflow').first().json.pergunta || '',
  pergunta_original: resolucaoBusca.pergunta_original || $('When Executed by Another Workflow').first().json.pergunta || '',
  consultar_base_conhecimento: Boolean(resolucaoBusca.consultar_base_conhecimento),
  tipo_intencao: resolucaoBusca.tipo_intencao || null,
  metodo_busca: resolucaoBusca.metodo_busca || null,
  identificadores_fortes: Array.isArray(resolucaoBusca.identificadores_fortes) ? resolucaoBusca.identificadores_fortes : [],
  documentos_apresentados: Array.isArray(resolucaoBusca.documentos_apresentados) ? resolucaoBusca.documentos_apresentados : [],
  documentos_rejeitados: Array.isArray(resolucaoBusca.documentos_rejeitados) ? resolucaoBusca.documentos_rejeitados : [],
  usar_documento_ativo: Boolean(resolucaoBusca.usar_documento_ativo),
  documento_ativo_id: resolucaoBusca.documento_ativo_id || null,
  documento_ativo_titulo: resolucaoBusca.documento_ativo_titulo || null,
  precisa_clarificacao: Boolean(resolucaoBusca.precisa_clarificacao),
  pergunta_clarificacao: resolucaoBusca.pergunta_clarificacao || null,
  assunto_ativo: resolucaoBusca.assunto_ativo || null,
  entidades_ativas: resolucaoBusca.entidades_ativas || {},
  total_tokens_contexto_busca: total_tokens,
  debug_busca_chunks: {
    metodo_busca: resolucaoBusca.metodo_busca || null,
    usou_embedding: total_tokens_embeddings > 0,
    total_tokens_resolucao_busca: total_tokens_contextoIA,
    total_tokens_embeddings
  }
};

if (!Array.isArray(chunks) || chunks.length === 0) {
  return [
    {
      json: {
        _tipo: 'sem_chunks',
        conteudo: null,
        ...metadata
      }
    }
  ];
}

return chunks.map(item => ({
  json: {
    ...item,
    ...metadata
  }
}));

function parseJsonSafe(value, fallback) {
  if (!value) return fallback;
  if (Array.isArray(value) || typeof value === 'object') return value;
  try { return JSON.parse(value); } catch { return fallback; }
}

const clean = (value) => String(value || '').trim();
const entrada = $('When Executed by Another Workflow').first().json || {};
const perguntaAtual = clean(entrada.pergunta);
const contextoAtivo = $input.first().json || {};
const entidadesAtivas = contextoAtivo.entidades_ativas && typeof contextoAtivo.entidades_ativas === 'object'
  ? contextoAtivo.entidades_ativas
  : {};
const historico = parseJsonSafe(entrada.historico_recente || '[]', [])
  .map((item) => item.json || item)
  .filter((item) => item && clean(item.mensagem))
  .slice(-6)
  .map((item) => ({ mensagem: clean(item.mensagem) }));

const schema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    tipo_intencao: {
      type: 'string',
      enum: ['historico', 'institucional', 'busca_servico', 'mostrar_mais_empresarios', 'cadastro', 'atendimento_humano', 'fora_escopo', 'clarificacao']
    },
    dominio_busca: { type: 'string', enum: ['nenhum', 'institucional', 'empresarios'] },
    modo_contexto: { type: 'string', enum: ['nova_busca', 'continuar_busca', 'sem_busca'] },
    consultar_base_conhecimento: { type: 'boolean' },
    metodo_busca: { type: 'string', enum: ['nenhum', 'vetorial', 'lexical', 'hibrido'] },
    pergunta_busca: { type: 'string' },
    necessidade: { type: 'string' },
    resposta_espera: { type: 'string' },
    precisa_clarificacao: { type: 'boolean' },
    pergunta_clarificacao: { type: 'string' },
    categoria_servico: { type: 'string' },
    assunto_ativo: { type: 'string' },
    entidades_ativas: {
      type: 'object',
      additionalProperties: false,
      properties: {
        profissao: { type: 'string' },
        categoria: { type: 'string' },
        servico: { type: 'string' },
        problema: { type: 'string' },
        empresa: { type: 'string' },
        produto: { type: 'string' }
      },
      required: ['profissao', 'categoria', 'servico', 'problema', 'empresa', 'produto']
    },
    identificadores_fortes: { type: 'array', items: { type: 'string' } },
    usar_documento_ativo: { type: 'boolean' },
    motivo: { type: 'string' }
  },
  required: [
    'tipo_intencao', 'dominio_busca', 'modo_contexto', 'consultar_base_conhecimento', 'metodo_busca',
    'pergunta_busca', 'necessidade', 'resposta_espera', 'precisa_clarificacao',
    'pergunta_clarificacao', 'categoria_servico', 'assunto_ativo', 'entidades_ativas',
    'identificadores_fortes', 'usar_documento_ativo', 'motivo'
  ]
};

const body = {
  model: 'google/gemini-2.5-flash',
  temperature: 0,
  max_tokens: 800,
  reasoning: { enabled: false },
  response_format: {
    type: 'json_schema',
    json_schema: {
      name: 'elo_triagem_busca',
      strict: true,
      schema
    }
  },
  messages: [
    {
      role: 'system',
      content: [
        'Você faz somente a triagem da Elo Connect e não responde diretamente ao usuário.',
        'Preencha exatamente o schema solicitado. Use string vazia quando um campo textual não se aplicar.',
        'tipo_intencao classifica a mensagem. dominio_busca vale empresarios somente para busca de profissional, empresa, produto ou serviço; institucional somente para informações oficiais da Elo.',
        'Use mostrar_mais_empresarios quando o usuário pedir os resultados restantes da última busca.',
        'modo_contexto é nova_busca quando a mensagem contém um pedido completo ou muda a profissão, categoria, serviço ou problema pesquisado. Nesse caso, ignore totalmente a pesquisa anterior.',
        'modo_contexto é continuar_busca somente para resposta curta a uma pergunta de esclarecimento, referência explícita à busca anterior ou pedido para mostrar mais. Uma busca já concluída não deve influenciar uma nova solicitação.',
        'modo_contexto é sem_busca quando a intenção não é pesquisa de empresários.',
        'Quando a mensagem informar apenas uma atividade ampla e não houver dados suficientes para distinguir a necessidade, faça uma única pergunta objetiva de esclarecimento.',
        'Se existe busca_empresarios pendente e a mensagem apenas complementa o que faltava, use continuar_busca, busca_servico e não faça uma segunda pergunta. Se a mensagem traz um novo pedido autônomo, use nova_busca e não combine os assuntos.',
        'pergunta_busca deve ser uma única frase natural e coerente para busca textual e semântica, com no máximo 20 palavras e 160 caracteres.',
        'Não produza listas de sinônimos, palavras separadas por vírgula, repetições, atributos comerciais, qualidades pessoais ou associações religiosas.',
        'necessidade descreve objetivamente o problema, serviço ou resultado procurado. categoria_servico é texto livre e deve preservar a atividade informada pelo usuário, sem escolher valores de uma lista fechada.',
        'pergunta_busca deve representar a necessidade completa em linguagem natural; categoria_servico pode registrar a atividade mencionada, sem controlar a pesquisa.',
        'Toda a operação é de Blumenau/SC. Nunca pergunte, extraia ou use cidade e estado para filtrar ou ranquear empresários.',
        'Pedidos que dependem somente do histórico usam historico e domínio nenhum.',
        'Nunca invente empresário, documento ou dado. Preserve somente entidades realmente presentes na mensagem ou no contexto.'
      ].join('\n')
    },
    {
      role: 'user',
      content: JSON.stringify({
        mensagem_atual: perguntaAtual,
        contexto_ativo: {
          assunto_ativo: contextoAtivo.assunto_ativo || null,
          entidades_ativas: entidadesAtivas,
          ultima_pergunta: contextoAtivo.ultima_pergunta || null,
          ultima_resposta: contextoAtivo.ultima_resposta || null
        },
        historico
      })
    }
  ]
};

return [{ json: {
  pergunta_atual: perguntaAtual,
  contexto_ativo: contextoAtivo,
  mensagens_recentes: historico,
  body_resolucao_busca: body
} }];

const clean = (value) => String(value || '').trim();
const parse = (value, fallback = null) => {
  if (!value) return fallback;
  if (typeof value === 'object') return value;
  const text = String(value).trim();
  try { return JSON.parse(text); } catch {}
  const match = text.match(/\{[\s\S]*\}/);
  if (match) { try { return JSON.parse(match[0]); } catch {} }
  return fallback;
};
const normalizarConsulta = (value, fallback) => {
  const texto = clean(value).replace(/\s+/g, ' ');
  if (!texto || texto.length > 240) return clean(fallback);
  const partes = texto.split(/[,;|]+/).map(clean).filter(Boolean);
  if (partes.length > 8) return clean(fallback);
  const unicas = new Set(partes.map((item) => item.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()));
  if (partes.length >= 4 && unicas.size / partes.length < 0.75) return clean(fallback);
  return texto;
};
const compactarEntidades = (value) => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  return Object.fromEntries(Object.entries(value).filter(([, item]) => clean(item)));
};

const payload = $('Montar payload resolucao de busca').first().json || {};
const contexto = payload.contexto_ativo || {};
const entidadesContexto = contexto.entidades_ativas && typeof contexto.entidades_ativas === 'object'
  ? contexto.entidades_ativas
  : {};
const content = $json.choices?.[0]?.message?.content || '';
const finishReason = clean($json.choices?.[0]?.finish_reason).toLowerCase();
const nativeFinishReason = clean($json.choices?.[0]?.native_finish_reason).toUpperCase();
const respostaTruncada = finishReason === 'length' || nativeFinishReason === 'MAX_TOKENS';
const parsedResponse = respostaTruncada ? null : parse(content, null);
const parsed = parsedResponse && typeof parsedResponse === 'object' && !Array.isArray(parsedResponse)
  ? parsedResponse
  : {};
const usage = $json.usage || {};
const permitidos = ['historico','institucional','busca_servico','mostrar_mais_empresarios','cadastro','atendimento_humano','fora_escopo','clarificacao'];
const dominios = ['nenhum','institucional','empresarios'];
const modosContexto = ['nova_busca','continuar_busca','sem_busca'];
const metodos = ['nenhum','vetorial','lexical','hibrido'];
const pergunta = clean(payload.pergunta_atual);

let tipo = clean(parsed.tipo_intencao).toLowerCase();
if (!permitidos.includes(tipo)) tipo = 'historico';
let dominio = clean(parsed.dominio_busca).toLowerCase();
if (!dominios.includes(dominio)) {
  dominio = ['busca_servico','mostrar_mais_empresarios'].includes(tipo)
    ? 'empresarios'
    : (tipo === 'institucional' ? 'institucional' : 'nenhum');
}

const estadoBusca = entidadesContexto.busca_empresarios && typeof entidadesContexto.busca_empresarios === 'object'
  ? entidadesContexto.busca_empresarios
  : null;
const pedidoMaisDeterministico = /\b(mostrar|ver|quero|mande|envie|exibir|exiba)\b.*\b(mais|restante|resto|outro|outros)\b/i.test(pergunta);
const pedidoNovoDeterministico = /\b(me indique|indique|indicação|procuro|busco|(?:eu\s+)?quero(?!\s+(?:mais|ver|mostrar))|preciso de|encontre|empresas? que|profissionais? que)\b/i.test(pergunta);
let modoContexto = clean(parsed.modo_contexto).toLowerCase();
if (!modosContexto.includes(modoContexto)) {
  modoContexto = tipo === 'busca_servico' ? 'nova_busca' : 'sem_busca';
}
if (pedidoMaisDeterministico && estadoBusca?.resultados?.length) {
  tipo = 'mostrar_mais_empresarios';
  dominio = 'empresarios';
  modoContexto = 'continuar_busca';
} else if (tipo === 'busca_servico' && pedidoNovoDeterministico) {
  modoContexto = 'nova_busca';
}
const buscaPendenteRespondida = Boolean(
  estadoBusca?.pendente &&
  pergunta &&
  !pedidoMaisDeterministico &&
  modoContexto === 'continuar_busca'
);
if (buscaPendenteRespondida) {
  tipo = 'busca_servico';
  dominio = 'empresarios';
}
if (tipo === 'busca_servico' && !buscaPendenteRespondida) modoContexto = 'nova_busca';
if (!['busca_servico','mostrar_mais_empresarios'].includes(tipo)) modoContexto = 'sem_busca';

const consultaModelo = normalizarConsulta(parsed.pergunta_busca, pergunta);
const necessidade = normalizarConsulta(parsed.necessidade, buscaPendenteRespondida ? pergunta : '');
const entidadesBase = { ...entidadesContexto };
if (modoContexto === 'nova_busca') delete entidadesBase.busca_empresarios;
const entidadesParsed = compactarEntidades(parsed.entidades_ativas);
const entidadesAtivas = { ...entidadesBase, ...entidadesParsed, tipo_intencao: tipo, dominio_busca: dominio };
const consultar = dominio === 'institucional' || (dominio === 'empresarios' && tipo !== 'clarificacao');
let metodo = clean(parsed.metodo_busca).toLowerCase();
if (!metodos.includes(metodo)) metodo = dominio === 'institucional' ? 'vetorial' : (dominio === 'empresarios' ? 'hibrido' : 'nenhum');
const triagemValida = !respostaTruncada && permitidos.includes(clean(parsed.tipo_intencao).toLowerCase());

return [{ json: {
  pergunta_original: pergunta,
  pergunta_busca: consultaModelo || pergunta,
  consulta_semantica: consultaModelo || pergunta,
  necessidade: necessidade || null,
  resposta_espera: clean(parsed.resposta_espera) || null,
  tipo_intencao: tipo,
  dominio_busca: dominio,
  modo_contexto: modoContexto,
  consultar_base_conhecimento: consultar,
  metodo_busca: metodo,
  categoria_servico: clean(parsed.categoria_servico) || null,
  cidade: null,
  estado: null,
  precisa_clarificacao: buscaPendenteRespondida ? false : Boolean(parsed.precisa_clarificacao || tipo === 'clarificacao'),
  pergunta_clarificacao: clean(parsed.pergunta_clarificacao) || null,
  assunto_ativo: clean(parsed.assunto_ativo) || (modoContexto === 'nova_busca' ? pergunta : clean(contexto.assunto_ativo)) || pergunta,
  entidades_ativas: entidadesAtivas,
  documento_ativo_id: dominio === 'institucional' ? (contexto.documento_ativo_id || null) : null,
  documento_ativo_titulo: dominio === 'institucional' ? (contexto.documento_ativo_titulo || null) : null,
  usar_documento_ativo: Boolean(dominio === 'institucional' && parsed.usar_documento_ativo && contexto.documento_ativo_id),
  identificadores_fortes: Array.isArray(parsed.identificadores_fortes)
    ? [...new Set(parsed.identificadores_fortes.map(clean).filter(Boolean))].slice(0, 8)
    : [],
  documentos_apresentados: Array.isArray(entidadesAtivas.documentos_apresentados) ? entidadesAtivas.documentos_apresentados : [],
  documentos_rejeitados: Array.isArray(entidadesAtivas.documentos_rejeitados) ? entidadesAtivas.documentos_rejeitados : [],
  motivo: clean(parsed.motivo) || (respostaTruncada ? 'Resposta da triagem truncada; consulta original preservada.' : 'Triagem sem JSON válido; consulta original preservada.'),
  triagem_valida: triagemValida,
  resposta_truncada: respostaTruncada,
  total_tokens_resolucao_busca: Number(usage.total_tokens || 0)
} }];

